function assertNever(x: never): never {
  throw new Error(`Unhandled case: ${x}`);
}

type ApiState =
  | { status: 'loading' }
  | { status: 'ok'; data: string[] }
  | { status: 'err'; error: Error };

function pickProp<T, K extends keyof T>(obj: T, key: K): T[K] {
  return obj[key];
}

interface User { id: string; email: string; passwordHash: string; }
type PublicUser = Omit<User, 'passwordHash'>;
type UserPatch = Partial<Pick<User, 'email'>>;

function isError(val: unknown): val is { message: string } {
  return typeof val === 'object' && val !== null && 'message' in val;
}

type EventHandlers<T extends string> = {
  [K in T as `on${Capitalize<K>}`]: () => void;
};
